const app=document.getElementById('app');function save(){s.saveDate=Date.now();localStorage.setItem('touchline-save',JSON.stringify(s))}function escapeHTML(value){return String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}function money(n){return '£'+Math.round(n).toLocaleString('en-GB')}function club(){return clubs.find(c=>c.name===s.club)||clubs[0]}function notify(t){const el=document.querySelector('.toast');if(!el)return;el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function shell(content){app.innerHTML=`<div class="shell"><header class="topbar"><div class="brand"><div class="brandmark">✦</div><div>TOUCHLINE<small>PRO CAREER</small></div></div><nav class="nav">${[['home','Career'],['drive','Drive'],['training','Training'],['match','Matchday'],['life','My Life'],['clubhouse','Clubhouse'],['house','My House'],['profile','Profile']].map(([id,label])=>`<button class="${screen===id?'active':''}" onclick="go('${id}')">${label}</button>`).join('')}</nav><div class="topright"><div class="money">◈ ${money(s.money)}</div><div class="avatar">${s.girlfriend?'🤍':'👤'}</div></div></header><main class="page">${content}</main><div class="toast"></div></div>`;}
function startScreen(){const greeting=s.started?`Welcome back, ${escapeHTML(s.name.split(' ')[0])}. Your next chapter starts here.`:'Build your name. Live your life. Own every moment.';shell(`<section class="hero"><div><div class="eyebrow">SEASON ${s.season} · WEEK ${s.week}</div><h1>${s.started?'The road to greatness':'Your career starts now'}</h1><p>${greeting}</p></div><div class="week-pill">WEEKLY PAY <b>${money(s.salary)}</b></div></section><section class="grid"><article class="card player-card"><div class="player-info"><div><div class="position">${s.started?s.nation.toUpperCase()+' · ATTACKING MIDFIELDER':'ACADEMY PROSPECT · #10'}</div><div class="player-name">${s.started?escapeHTML(s.name):'YOUR<br>PLAYER'}</div><div class="player-sub">${s.club} &nbsp;·&nbsp; Age ${s.age} &nbsp;·&nbsp; ${s.outfit}</div></div><div class="rating"><div><b>${s.rating}<span style="font-size:10px;color:var(--lime)"> OVR</span></b><span>RATING</span></div><div><b>${s.goals}</b><span>GOALS</span></div><div><b>${s.fitness}%</b><span>FITNESS</span></div></div></div><div class="player-figure"><div class="hair"></div><div class="head"></div><div class="body"></div><div class="shirtline"></div><div class="number">10</div><div class="shorts"></div><div class="leg l"></div><div class="leg r"></div><div class="sock l"></div><div class="sock r"></div><div class="boot l"></div><div class="boot r"></div><div class="ball">⚽</div></div></article><article class="card cardpad matchcard"><div class="cardhead"><h3>Next fixture</h3><span class="tiny">${s.week%2?'LEAGUE':'CUP'}</span></div><div class="fixture"><div class="club"><div class="crest">${club().short}</div>${club().name}</div><div class="vs">VS</div><div class="club"><div class="crest away">${['Rovers FC','City Athletic','Harbor Town','Eastvale'][s.week%4].slice(0,2).toUpperCase()}</div>${['Rovers FC','City Athletic','Harbor Town','Eastvale'][s.week%4]}</div></div><div class="matchmeta">TODAY &nbsp;·&nbsp; ${s.played===0?'FIRST KICKOFF':'MATCHDAY '+(s.played+1)}</div><button class="btn btn-primary" onclick="go('match')">▶ &nbsp; PLAY HIGHLIGHTS</button></article><article class="card formcard"><div class="cardhead"><h3>Season form</h3><span class="tiny">LAST 5</span></div><div class="formlist">${Array.from({length:5},(_,i)=>{let r=s.lastResults?.[i]||'—';return `<div class="formdot ${r==='W'?'win':r==='D'?'draw':r==='L'?'loss':''}">${r}</div>`}).join('')}</div><div class="formcaption">${s.lastResult}</div><div class="streak"><span>CAREER APPEARANCES</span><strong>${s.played}</strong></div></article></section><h2 class="section-title">Make your move</h2><section class="quickgrid"><article class="card quick" onclick="go('life')"><div class="quickicon">🏋️</div><b>Train & recover</b><span>Get match-fit at the gym</span></article><article class="card quick" onclick="go('clubhouse')"><div class="quickicon">🛍️</div><b>Hit the mall</b><span>Find a fit that feels like you</span></article><article class="card quick" onclick="go('clubhouse');setTimeout(()=>clubTab('transfers'),0)"><div class="quickicon">✈️</div><b>Transfer market</b><span>Find your next club</span></article><article class="card quick" onclick="go('life')"><div class="quickicon">📺</div><b>Switch off</b><span>TV, games & downtime</span></article></section><section class="dashboard-bottom"><article class="card news"><div class="cardhead"><h3>Touchline talk</h3><span class="tiny">LATEST</span></div><div class="newsrow"><span class="newsicon">📰</span><div><b>${s.played?`${s.name} turns heads after ${s.lastResult.includes('Win')?'a standout performance':'a big week'} for ${s.club}`:'New season, new story: the academy prospect to watch'}</b><p>Club insiders are excited to see what the season brings.</p></div></div></article><article class="card contract"><div class="cardhead"><h3>Contract details</h3><span class="tiny">${s.contract} WEEKS LEFT</span></div><div class="contractline"><span>Weekly wage</span><strong>${money(s.salary)}</strong></div><div class="contractline"><span>Club</span><strong>${s.club}</strong></div><div class="progress"><i style="width:${Math.max(8,Math.min(100,(s.contract/24)*100))}%"></i></div></article></section>`)}
function go(to){if(screen==='match'&&to!=='match'){clearInterval(matchLoop);matchLoop=null;stopMove();window.onkeydown=null;window.onkeyup=null;activeMatch=null;if(trainingMode){trainingMode=false;if(preTrainingScenario)activeScenario=preTrainingScenario;preTrainingScenario=null}}if(screen==='drive'&&to!=='drive'){clearInterval(driveTimer);cancelAnimationFrame(driveFrame);window.removeEventListener('keydown',driveKeyDown);window.removeEventListener('keyup',driveKeyUp);window.removeEventListener('resize',drawDrive);driveTimer=null;driveFrame=null;driveKeys={};driveState=null}if(screen==='training'&&to!=='training'){cancelAnimationFrame(trainingFrame);window.removeEventListener('keydown',trainingKeyDown);trainingFrame=null;trainingState=null}screen=to;if(to==='home')render();else if(to==='match')renderMatch();else if(to==='drive')renderDrive();else if(to==='training')renderTraining();else if(to==='life')renderLife();else if(to==='clubhouse')renderClubhouse('transfers');else if(to==='house')renderHouse();else if(to==='profile')renderProfile();}
function renderDrive(){driveState={started:false,finished:false,lane:1,distance:0,speed:72,traffic:[],spawnIn:1.1,lastTime:0,crashCooldown:0};driveKeys={};shell(`<section class="page-head"><div><div class="eyebrow">MATCHDAY ${s.played+1} · ROAD TO THE STADIUM</div><h1>Drive to the game</h1><p>Weave through traffic and make kickoff. Use ← / → or the on-screen controls to change lanes.</p></div><div class="week-pill">DESTINATION <b>${escapeHTML(s.club)}</b></div></section><section class="drive-layout"><article class="card drive-card"><div class="drive-hud"><span id="driveStatus">READY TO DEPART</span><span>ROAD SPEED <b id="driveSpeed">72 km/h</b></span><span>JOURNEY <b id="driveDistance">0 / 1,800 m</b></span></div><canvas id="driveCanvas" aria-label="Driving road game"></canvas><div class="drive-progress"><i id="driveProgress"></i></div><div class="drive-controls"><button class="btn btn-dark" onclick="steerDrive(-1)" aria-label="Steer left">← LEFT</button><button class="btn btn-primary" id="driveStart" onclick="startDrive()">START DRIVE</button><button class="btn btn-dark" onclick="steerDrive(1)" aria-label="Steer right">RIGHT →</button></div><div class="drive-pedals"><button class="btn btn-dark" onpointerdown="setDrivePedal('brake',true)" onpointerup="setDrivePedal('brake',false)" onpointerleave="setDrivePedal('brake',false)" onpointercancel="setDrivePedal('brake',false)">BRAKE</button><button class="btn btn-dark" onpointerdown="setDrivePedal('accelerate',true)" onpointerup="setDrivePedal('accelerate',false)" onpointerleave="setDrivePedal('accelerate',false)" onpointercancel="setDrivePedal('accelerate',false)">ACCELERATE</button></div><p class="tiny drive-help">Avoid the other cars. A collision slows you down; reach the stadium to continue to Matchday.</p></article><aside class="card panel drive-aside"><div class="eyebrow">YOUR FIXTURE</div><h2>${escapeHTML(s.club)}</h2><p>It is matchday. Take the road to the stadium, then step onto the pitch.</p><div class="contractline"><span>Kickoff</span><strong>Today · 15:00</strong></div><div class="contractline"><span>Fitness</span><strong>${s.fitness}%</strong></div><button class="btn btn-dark" style="width:100%;margin-top:14px" onclick="go('home')">BACK TO CAREER</button></aside></section>`);const canvas=document.getElementById('driveCanvas');if(canvas){canvas.addEventListener('pointerdown',e=>{if(!driveState?.started||driveState.finished)return;const r=canvas.getBoundingClientRect();steerDrive((e.clientX-r.left)<r.width/2?-1:1)});drawDrive()}window.addEventListener('resize',drawDrive)}
function startDrive(){if(!driveState||driveState.finished||driveState.started)return;driveState.started=true;driveState.lastTime=performance.now();const btn=document.getElementById('driveStart');if(btn){btn.textContent='DRIVING…';btn.disabled=true}window.addEventListener('keydown',driveKeyDown);window.addEventListener('keyup',driveKeyUp);driveFrame=requestAnimationFrame(updateDrive);updateDriveHud()}
function driveKeyDown(e){if(screen!=='drive'||!driveState?.started||driveState.finished)return;const k=e.key.toLowerCase();if(['arrowleft','a'].includes(k)){e.preventDefault();if(!e.repeat)steerDrive(-1)}else if(['arrowright','d'].includes(k)){e.preventDefault();if(!e.repeat)steerDrive(1)}else if(['arrowup','w'].includes(k)){e.preventDefault();driveKeys.accelerate=true}else if(['arrowdown','s'].includes(k)){e.preventDefault();driveKeys.brake=true}}
function driveKeyUp(e){const k=e.key.toLowerCase();if(['arrowup','w'].includes(k))driveKeys.accelerate=false;if(['arrowdown','s'].includes(k))driveKeys.brake=false}
function setDrivePedal(pedal,pressed){if(driveState?.started&&!driveState.finished)driveKeys[pedal]=pressed}
function steerDrive(direction){if(!driveState?.started||driveState.finished)return;driveState.lane=Math.max(0,Math.min(2,driveState.lane+direction));drawDrive()}
function updateDrive(){if(screen!=='drive'||!driveState?.started||driveState.finished)return;const now=performance.now(),dt=Math.min(.05,Math.max(0,(now-driveState.lastTime)/1000));driveState.lastTime=now;driveState.speed=Math.max(35,Math.min(130,driveState.speed+(driveKeys.accelerate?42:driveKeys.brake?-60:-6)*dt));driveState.distance+=driveState.speed/3.6*12*dt;driveState.spawnIn-=dt;driveState.crashCooldown=Math.max(0,driveState.crashCooldown-dt);if(driveState.spawnIn<=0){driveState.traffic.push({lane:Math.floor(Math.random()*3),y:-45});driveState.spawnIn=.85+Math.random()*.75}driveState.traffic.forEach(car=>car.y+=(125+driveState.speed*.35)*dt);driveState.traffic=driveState.traffic.filter(car=>car.y<470);for(const car of driveState.traffic){if(car.lane===driveState.lane&&car.y>330&&car.y<405&&driveState.crashCooldown===0){driveState.speed=Math.max(35,driveState.speed-30);driveState.crashCooldown=1.1;car.y=450;notify('Traffic bump — watch the road!')}}if(driveState.distance>=1800){driveState.distance=1800;driveState.finished=true;window.removeEventListener('keydown',driveKeyDown);window.removeEventListener('keyup',driveKeyUp);const status=document.getElementById('driveStatus'),btn=document.getElementById('driveStart');if(status)status.textContent='ARRIVED AT THE STADIUM';if(btn){btn.textContent='CONTINUE TO MATCHDAY →';btn.disabled=false;btn.onclick=()=>go('match')}notify('You made it to the stadium — kickoff is next!')}updateDriveHud();drawDrive();if(!driveState.finished)driveFrame=requestAnimationFrame(updateDrive)}
function updateDriveHud(){if(!driveState)return;const speed=document.getElementById('driveSpeed'),distance=document.getElementById('driveDistance'),progress=document.getElementById('driveProgress'),status=document.getElementById('driveStatus');if(speed)speed.textContent=`${Math.round(driveState.speed)} km/h`;if(distance)distance.textContent=`${Math.floor(driveState.distance).toLocaleString()} / 1,800 m`;if(progress)progress.style.width=`${Math.min(100,driveState.distance/18)}%`;if(status&&driveState.started&&!driveState.finished)status.textContent='ON THE ROAD · AVOID TRAFFIC'}
function drawDrive(){const canvas=document.getElementById('driveCanvas');if(!canvas)return;const r=canvas.getBoundingClientRect();if(!r.width||!r.height)return;const d=Math.min(window.devicePixelRatio||1,2);if(canvas.width!==Math.round(r.width*d)||canvas.height!==Math.round(r.height*d)){canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d)}const g=canvas.getContext('2d'),w=800,h=420;g.setTransform(canvas.width/w,0,0,canvas.height/h,0,0);const sky=g.createLinearGradient(0,0,0,h);sky.addColorStop(0,'#527781');sky.addColorStop(.52,'#a9b58b');sky.addColorStop(.53,'#262d29');sky.addColorStop(1,'#111713');g.fillStyle=sky;g.fillRect(0,0,w,h);g.fillStyle='#324b38';g.fillRect(0,205,w,55);g.fillStyle='#292e2c';g.beginPath();g.moveTo(160,205);g.lineTo(640,205);g.lineTo(760,420);g.lineTo(40,420);g.closePath();g.fill();g.strokeStyle='#e8dfb8';g.lineWidth=5;g.beginPath();g.moveTo(160,205);g.lineTo(40,420);g.moveTo(640,205);g.lineTo(760,420);g.stroke();const offset=(driveState?.distance||0)%90;g.strokeStyle='#e8dfb877';g.lineWidth=4;g.setLineDash([25,22]);g.lineDashOffset=-offset;for(let i=1;i<=2;i++){const x=160+i*160;g.beginPath();g.moveTo(x,205);g.lineTo(40+i*240,420);g.stroke()}g.setLineDash([]);g.fillStyle='#e9e3ce';g.font='bold 14px sans-serif';g.textAlign='center';g.fillText('STADIUM  →',400,190);(driveState?.traffic||[]).forEach(car=>{const x=160+car.lane*160+(car.y-205)*.28,y=car.y,scale=.55+Math.max(0,y-205)/500;g.fillStyle='#111';g.fillRect(x-18*scale,y-24*scale,36*scale,48*scale);g.fillStyle=['#e37454','#67a8c9','#dbcc79'][car.lane];g.fillRect(x-15*scale,y-21*scale,30*scale,37*scale);g.fillStyle='#ffe9ad';g.fillRect(x-12*scale,y+12*scale,7*scale,4*scale);g.fillRect(x+5*scale,y+12*scale,7*scale,4*scale)});const px=160+driveState.lane*160+(400-205)*.28;g.fillStyle='#101412';g.beginPath();g.roundRect(px-24,334,48,70,10);g.fill();g.fillStyle='#c7f36b';g.beginPath();g.roundRect(px-20,339,40,58,8);g.fill();g.fillStyle='#b8d7dc';g.fillRect(px-15,345,30,17);g.fillStyle='#ff5a47';g.fillRect(px-17,387,8,7);g.fillRect(px+9,387,8,7);g.fillStyle='#f6f1dc';g.font='bold 11px sans-serif';g.fillText('YOU',px,378);g.setTransform(1,0,0,1,0,0)}
function renderTraining(){trainingState={started:false,finished:false,score:0,time:30,target:{x:.5,y:.46},lastTime:0};shell(`<section class="page-head"><div><div class="eyebrow">TRAINING GROUND · TECHNICAL DRILL</div><h1>Sharpen your touch</h1><p>Hit the moving targets with a click, tap, or swipe. Score five hits to earn a rating boost.</p></div><div class="week-pill">PLAYER RATING <b>${s.rating} OVR</b></div></section><section class="training-layout"><article class="card training-card"><div class="training-hud"><span id="trainingStatus">READY TO TRAIN</span><span>HITS <b id="trainingScore">0</b></span><span>TIME <b id="trainingTime">30s</b></span></div><canvas id="trainingCanvas" aria-label="Football passing and shooting drill"></canvas><div class="training-controls"><button class="btn btn-primary" id="trainingStart" onclick="startTraining()">START DRILL</button><button class="btn btn-dark" onclick="trainingHit()">⚽ &nbsp; PASS / SHOOT</button></div><p class="tiny">Click or tap the glowing target, or swipe across the drill area. Complete the drill to improve your player.</p></article><aside class="card panel"><div class="eyebrow">TRAINING REWARDS</div><h2>Every touch counts</h2><p>Make five or more successful touches in 30 seconds to gain +1 OVR and +5 fitness. Training uses a little energy.</p><div class="contractline"><span>Current rating</span><strong>${s.rating} OVR</strong></div><div class="contractline"><span>Fitness</span><strong>${s.fitness}%</strong></div><div class="contractline"><span>Energy</span><strong>${s.energy}%</strong></div></aside></section>`);const canvas=document.getElementById('trainingCanvas');if(canvas){let down=null;canvas.addEventListener('pointerdown',e=>{const r=canvas.getBoundingClientRect();down={x:e.clientX-r.left,y:e.clientY-r.top}});canvas.addEventListener('pointerup',e=>{if(!trainingState?.started||trainingState.finished)return;const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,t=trainingState.target,tx=t.x*r.width,ty=t.y*r.height;if(Math.hypot(x-tx,y-ty)<68||down&&Math.hypot(x-down.x,y-down.y)>35)trainingHit()});drawTraining()}}
function startTraining(){if(!trainingState||trainingState.started||trainingState.finished)return;trainingState.started=true;trainingState.lastTime=performance.now();const btn=document.getElementById('trainingStart');if(btn){btn.textContent='DRILL IN PROGRESS';btn.disabled=true}window.addEventListener('keydown',trainingKeyDown);trainingFrame=requestAnimationFrame(updateTraining)}
function trainingKeyDown(e){if(screen==='training'&&trainingState?.started&&!trainingState.finished&&(e.code==='Space'||e.key.toLowerCase()==='e')){e.preventDefault();trainingHit()}}
function trainingHit(){if(!trainingState?.started||trainingState.finished)return;trainingState.score++;trainingState.target={x:.12+Math.random()*.76,y:.2+Math.random()*.6};const score=document.getElementById('trainingScore');if(score)score.textContent=trainingState.score;drawTraining()}
function updateTraining(){if(screen!=='training'||!trainingState?.started||trainingState.finished)return;const now=performance.now();trainingState.time=Math.max(0,trainingState.time-(now-trainingState.lastTime)/1000);trainingState.lastTime=now;const time=document.getElementById('trainingTime');if(time)time.textContent=`${Math.ceil(trainingState.time)}s`;drawTraining();if(trainingState.time<=0){trainingState.finished=true;window.removeEventListener('keydown',trainingKeyDown);s.energy=Math.max(0,s.energy-8);if(trainingState.score>=5){s.rating=Math.min(99,s.rating+1);s.fitness=Math.min(100,s.fitness+5);notify(`Great session! ${s.name} gained +1 OVR and +5 fitness.`)}else notify(`Training complete: ${trainingState.score} hits. Try for five to earn a rating boost.`);save();const status=document.getElementById('trainingStatus'),btn=document.getElementById('trainingStart');if(status)status.textContent=trainingState.score>=5?'DRILL COMPLETE · GREAT WORK':'DRILL COMPLETE · KEEP PRACTISING';if(btn){btn.disabled=false;btn.textContent='TRAIN AGAIN';btn.onclick=()=>renderTraining()}return}trainingFrame=requestAnimationFrame(updateTraining)}
function drawTraining(){const canvas=document.getElementById('trainingCanvas');if(!canvas)return;const r=canvas.getBoundingClientRect();if(!r.width||!r.height)return;const d=Math.min(window.devicePixelRatio||1,2);if(canvas.width!==Math.round(r.width*d)||canvas.height!==Math.round(r.height*d)){canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d)}const g=canvas.getContext('2d'),w=800,h=360;g.setTransform(canvas.width/w,0,0,canvas.height/h,0,0);g.fillStyle='#426844';g.fillRect(0,0,w,h);g.strokeStyle='#d5e0bb';g.lineWidth=3;g.strokeRect(22,22,w-44,h-44);g.beginPath();g.moveTo(w/2,22);g.lineTo(w/2,h-22);g.stroke();g.beginPath();g.arc(w/2,h/2,52,0,Math.PI*2);g.stroke();g.fillStyle='#c7f36b';g.beginPath();g.arc(trainingState.target.x*w,trainingState.target.y*h,28,0,Math.PI*2);g.fill();g.strokeStyle='#f4f3e8';g.lineWidth=4;g.beginPath();g.arc(trainingState.target.x*w,trainingState.target.y*h,39,0,Math.PI*2);g.stroke();g.fillStyle='#17220d';g.font='bold 14px sans-serif';g.textAlign='center';g.fillText('HIT',trainingState.target.x*w,trainingState.target.y*h+5);g.fillStyle='#f4f3e8';g.font='bold 20px sans-serif';g.fillText('⚽',w*.5,h*.82);g.setTransform(1,0,0,1,0,0)}
const houseCatalog=[{name:'Monstera Plant',icon:'🪴',price:320,kind:'Greenery'},{name:'Club Colours Cushion',icon:'🛋️',price:450,kind:'Soft furnishing'},{name:'Framed Number 10',icon:'🖼️',price:560,kind:'Wall art'},{name:'Standing Lamp',icon:'💡',price:390,kind:'Lighting'},{name:'Football Shelf',icon:'⚽',price:280,kind:'Collectible'},{name:'Trophy Cabinet',icon:'🏆',price:1250,kind:'Furniture'},{name:'City Skyline Canvas',icon:'🌆',price:720,kind:'Wall art'},{name:'Cozy Rug',icon:'🧶',price:640,kind:'Flooring'}];let selectedHouseItem=null;const houseSpots=[['wall-left','Left wall'],['wall-center','Center wall'],['wall-right','Right wall'],['floor-left','Left corner'],['floor-center','Room center'],['floor-right','Right corner']];function buyHouseItem(name){const item=houseCatalog.find(x=>x.name===name);if(!item||s.houseItems.includes(name))return;if(!spend(item.price))return;s.houseItems.push(name);save();selectedHouseItem=name;renderHouse();notify(`${name} added to your home inventory`)}function placeHouseItem(spot){if(!houseSpots.some(([id])=>id===spot))return;const occupant=s.housePlacements[spot];if(!selectedHouseItem){if(occupant){selectedHouseItem=occupant;renderHouse();notify(`Selected ${occupant} — choose a new spot`)}else notify('Choose an item from your inventory first');return}if(!s.houseItems.includes(selectedHouseItem)){selectedHouseItem=null;return}const from=Object.keys(s.housePlacements).find(key=>s.housePlacements[key]===selectedHouseItem);if(from===spot){selectedHouseItem=null;renderHouse();return}const placements={...s.housePlacements};if(occupant){if(from)placements[from]=occupant;else delete placements[spot]}else if(from)delete placements[from];placements[spot]=selectedHouseItem;s.housePlacements=placements;const placed=selectedHouseItem;selectedHouseItem=null;save();renderHouse();notify(`${placed} placed in your home`)}function pickUpHouseItem(spot){const name=s.housePlacements[spot];if(!name)return;const placements={...s.housePlacements};delete placements[spot];s.housePlacements=placements;selectedHouseItem=name;save();renderHouse();notify(`${name} returned to your inventory`)}function renderHouse(){if(!Array.isArray(s.houseItems))s.houseItems=[];if(!s.housePlacements||typeof s.housePlacements!=='object')s.housePlacements={};const placedFor=spot=>{const name=s.housePlacements[spot],item=houseCatalog.find(x=>x.name===name);return item?`<span class="house-decor"><b>${item.icon}</b><small>${escapeHTML(item.name)}</small></span>`:`<span class="house-spot-hint">${selectedHouseItem?'PLACE HERE':'+'}</span>`};shell(`<section class="page-head"><div><div class="eyebrow">YOUR SPACE · YOUR STYLE</div><h1>Make yourself at home</h1><p>Buy decorations, choose an item from your inventory, then pick a spot in your room. Your home is saved with your career.</p></div><div class="week-pill">HOME COLLECTION <b>${s.houseItems.length} ITEMS</b></div></section><section class="house-layout"><article class="card house-room-card"><div class="house-room-heading"><div><div class="eyebrow">${escapeHTML(s.name)}'S PLACE</div><h2>Living room</h2></div><span class="tiny">${Object.keys(s.housePlacements).length} / ${houseSpots.length} PLACED</span></div><div class="house-room ${selectedHouseItem?'placing':''}"><div class="house-window"><i></i><i></i><i></i></div><div class="house-wall-shelf"></div><div class="house-couch"><span>TOUCHLINE</span></div><div class="house-table"></div><div class="house-rug"></div><div class="house-floor"></div>${houseSpots.map(([spot,label])=>{const name=s.housePlacements[spot],item=houseCatalog.find(x=>x.name===name);return `<button class="house-spot spot-${spot} ${item?'occupied':''} ${selectedHouseItem?'target':''}" aria-label="${item?escapeHTML(item.name)+' at '+label:'Place decoration at '+label}" title="${label}${item?' · '+item.name:''}" onclick="placeHouseItem('${spot}')">${placedFor(spot)}${item?`<span class="house-pickup" role="button" title="Pick up ${escapeHTML(item.name)}" onclick="event.stopPropagation();pickUpHouseItem('${spot}')">↗</span>`:''}</button>`}).join('')}<div class="house-player">👤<small>${escapeHTML(s.name.split(' ')[0])}</small></div></div><p class="tiny house-tip">${selectedHouseItem?`Placing: <b>${escapeHTML(selectedHouseItem)}</b> · choose a highlighted spot.`:'Select a decoration below, then click a spot in the room. Click an occupied item to move it.'}</p><div class="house-inventory"><div class="cardhead"><h3>Your decorations</h3><span class="tiny">${s.houseItems.length} OWNED</span></div>${s.houseItems.length?`<div class="house-owned-list">${s.houseItems.map(name=>{const item=houseCatalog.find(x=>x.name===name);if(!item)return '';const isPlaced=Object.values(s.housePlacements).includes(name);return `<button class="house-owned ${selectedHouseItem===name?'selected':''} ${isPlaced?'is-placed':''}" onclick="selectedHouseItem='${name}';renderHouse()"><span>${item.icon}</span><b>${escapeHTML(name)}</b><small>${isPlaced?'PLACED':'IN INVENTORY'}</small></button>`}).join('')}</div>`:'<p class="tiny">Your room is waiting for its first personal touch. Browse the home shop below.</p>'}</div></article><aside class="card house-shop"><div class="eyebrow">THE HOME SHOP</div><h2>Little things, big character</h2><p>Spend your career earnings on decorations. Every purchase stays in your collection.</p><div class="house-shop-balance">AVAILABLE BALANCE <b>${money(s.money)}</b></div><div class="house-shop-list">${houseCatalog.map(item=>{const owned=s.houseItems.includes(item.name);return `<article class="house-shop-item"><span class="house-shop-icon">${item.icon}</span><div><b>${escapeHTML(item.name)}</b><small>${item.kind}</small></div><button class="btn ${owned?'btn-dark':'btn-primary'}" ${owned||s.money<item.price?'disabled':''} onclick="buyHouseItem('${item.name}')">${owned?'OWNED':money(item.price)}</button></article>`}).join('')}</div></aside></section>`)}function render(){if(!s.started){renderCreate();return}startScreen()}
function renderCreate(){shell(`<section class="hero"><div><div class="eyebrow">A PLAYER'S STORY</div><h1>Write your own legacy</h1><p>Choose your nation, pick a name, and take your first step into the pros.</p></div></section><div class="card panel" style="max-width:900px;margin:auto"><div class="toolbar"><div><div class="eyebrow">01 — YOUR PLAYER</div><h2 style="font:800 27px 'Barlow Condensed';margin:7px 0">Create your pro</h2></div><div class="tiny">Your career autosaves on this device</div></div><label for="playerName" style="display:block;font-size:10px;color:var(--muted);margin:14px 0 6px">PLAYER NAME</label><input id="playerName" maxlength="30" placeholder="Enter your name" autocomplete="name" required class="select" style="width:100%;font-size:14px" onkeydown="if(event.key==='Enter')beginCareer()"><label style="display:block;font-size:10px;color:var(--muted);margin:20px 0 6px">CHOOSE YOUR NATION <span style="color:var(--lime)">(${countries.length} available)</span></label><div class="country-grid">${countries.map(([flag,name])=>`<div class="card country-option ${name===s.nation?'selected':''}" onclick="pickNation('${name}',this)"><span class="flag">${flag}</span><strong>${name}</strong><small>National team</small></div>`).join('')}</div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:22px;gap:12px;flex-wrap:wrap"><span style="font-size:10px;color:var(--muted)">Start at Northbridge FC · £8,400 weekly wage · Age 19</span><button class="btn btn-primary" onclick="beginCareer()">START MY CAREER &nbsp; →</button></div></div>`)}let selectedNation=s.nation;function pickNation(name,el){selectedNation=name;document.querySelectorAll('.country-option').forEach(x=>x.classList.remove('selected'));el.classList.add('selected')}function beginCareer(){const name=document.getElementById('playerName').value.trim();if(!name){notify('Add a player name first');return}s.name=name;s.nation=selectedNation;s.started=true;save();notify(`Welcome to the pros, ${name.split(' ')[0]}!`);render()}
let keysDown={},moveInterval=null;function renderMatch(){activeMatch={time:0,home:0,away:0,x:360,y:300,bx:410,by:300,hasBall:true,done:false,competition:'League',homeName:club().short,awayName:'ROV',log:'Kick off! Find space and make your mark.'};shell(`<section class="page-head"><div><div class="eyebrow">MATCHDAY ${s.played+1} · ${s.club.toUpperCase()}</div><h1>Make the moment</h1><p>Play the key highlights. Create chances, score goals, and lift your team.</p></div><div class="week-pill">FITNESS <b>${s.fitness}%</b></div></section><div class="toolbar"><div class="subtabs"><button class="active" onclick="setCompetition('League',this)">League</button><button onclick="setCompetition('UEFA Champions League',this)">UEFA Champions League</button><button onclick="setCompetition('World Cup',this)">World Cup</button></div><span class="tiny">Keyboard: WASD / arrows · Space shoots · E passes</span></div><section class="match-layout"><div class="pitch-wrap"><canvas id="pitch"></canvas><div class="match-overlay"><div class="scoreboard"><b id="scoreboard">NFC &nbsp; 0 — 0 &nbsp; ROV</b><span id="compLabel">LEAGUE · 1ST HALF</span></div><div class="minute" id="minute">01′</div></div></div><aside class="match-side"><div class="sidebox"><h3>Match controls</h3><p>Move into space, then take your chance. Your choices shape the highlights.</p><div class="controls"><div class="control-row"><button class="btn btn-dark" onpointerdown="holdMove('up')" onpointerup="stopMove()" onpointerleave="stopMove()">↑</button></div><div></div><button class="btn btn-dark" onpointerdown="holdMove('left')" onpointerup="stopMove()" onpointerleave="stopMove()">←</button><button class="btn btn-dark" onpointerdown="holdMove('down')" onpointerup="stopMove()" onpointerleave="stopMove()">↓</button><button class="btn btn-dark" onpointerdown="holdMove('right')" onpointerup="stopMove()" onpointerleave="stopMove()">→</button></div><div class="controls"><button class="btn btn-primary" onclick="shoot()">⚽ &nbsp; SHOOT</button><button class="btn btn-dark" onclick="passBall()">↗ &nbsp; PASS</button><button class="btn btn-orange" onclick="tackle()">✦ &nbsp; TACKLE</button><button class="btn btn-dark" onclick="playMoment()">⏩ &nbsp; NEXT MOMENT</button></div><p class="mobile-note">Touch and hold to move. Shoot near goal, pass to keep possession.</p></div><div class="sidebox"><h3>Match highlights</h3><p id="matchLog">${activeMatch.log}</p><div class="match-status" id="matchStatus">Ready for kickoff</div><div class="end-actions"><button class="btn btn-dark" onclick="forfeitMatch()">Leave match</button><button class="btn btn-primary hidden" id="continueBtn" onclick="finishMatch()">FULL TIME →</button></div></div></aside></section>`);initPitch();window.onkeydown=e=>{let k=e.key.toLowerCase();keysDown[k]=true;if(k===' '){e.preventDefault();shoot()}if(k==='e')passBall();if(k==='shift')tackle()};window.onkeyup=e=>keysDown[e.key.toLowerCase()]=false;startMatchLoop()}
function setCompetition(c,el){activeMatch.competition=c;if(c==='World Cup'){activeMatch.homeName=s.nation==='England'?'ENG':s.nation.slice(0,3).toUpperCase();activeMatch.awayName='MEX';activeMatch.log=`You are representing ${s.nation} in the World Cup. Make your country proud!`}else if(c==='UEFA Champions League'){activeMatch.homeName=club().short;activeMatch.awayName='PAR';activeMatch.log='Champions League night! The lights are on and Europe is watching.'}else{activeMatch.homeName=club().short;activeMatch.awayName='ROV';activeMatch.log='League kickoff! Find space and make your mark.'}document.querySelectorAll('.subtabs button').forEach(b=>b.classList.remove('active'));el.classList.add('active');document.getElementById('compLabel').textContent=c.toUpperCase()+' · 1ST HALF';document.querySelector('.eyebrow').textContent=`${c.toUpperCase()} · ${s.club.toUpperCase()}`}
function startMatchLoop(){clearInterval(matchLoop);matchLoop=setInterval(()=>{if(!activeMatch||activeMatch.done)return;activeMatch.time+=1;let dx=0,dy=0;if(keysDown['arrowup']||keysDown['w'])dy=-1;if(keysDown['arrowdown']||keysDown['s'])dy=1;if(keysDown['arrowleft']||keysDown['a'])dx=-1;if(keysDown['arrowright']||keysDown['d'])dx=1;if(dx||dy){activeMatch.x=Math.max(65,Math.min(935,activeMatch.x+dx*24));activeMatch.y=Math.max(105,Math.min(495,activeMatch.y+dy*24));if(activeMatch.hasBall){activeMatch.bx=activeMatch.x+25;activeMatch.by=activeMatch.y+8}}if(Math.random()<.17){activeMatch.bx+=Math.random()*100-50;activeMatch.by+=Math.random()*90-45;activeMatch.bx=Math.max(60,Math.min(940,activeMatch.bx));activeMatch.by=Math.max(90,Math.min(510,activeMatch.by));if(!activeMatch.hasBall&&Math.random()<.3){activeMatch.hasBall=true;activeMatch.x=activeMatch.bx;activeMatch.y=activeMatch.by;activeMatch.log='You win the ball back in midfield!';}}if(activeMatch.time>=9)endMatch();updateMatchHud();drawPitch()},1800)}
function initPitch(){const c=document.getElementById('pitch');if(!c)return;const resize=()=>{const r=c.getBoundingClientRect();const dpr=Math.min(devicePixelRatio||1,2);c.width=r.width*dpr;c.height=r.height*dpr;drawPitch()};new ResizeObserver(resize).observe(c);resize();c.addEventListener('pointerdown',e=>{const r=c.getBoundingClientRect();activeMatch.x=(e.clientX-r.left)/r.width*1000;activeMatch.y=(e.clientY-r.top)/r.height*600;if(activeMatch.hasBall){activeMatch.bx=activeMatch.x+20;activeMatch.by=activeMatch.y}drawPitch()})}
function drawPitch(){const c=document.getElementById('pitch');if(!c||!activeMatch)return;const g=c.getContext('2d'),w=c.width,h=c.height;g.clearRect(0,0,w,h);g.save();g.scale(w/1000,h/600);g.fillStyle='#15301f';g.fillRect(0,0,1000,600);for(let i=0;i<10;i++){g.fillStyle=i%2?'#1a3825':'#1d3d28';g.fillRect(i*100,0,100,600)}g.strokeStyle='#d5ead3a0';g.lineWidth=3;g.strokeRect(45,45,910,510);g.beginPath();g.moveTo(500,45);g.lineTo(500,555);g.stroke();g.beginPath();g.arc(500,300,75,0,Math.PI*2);g.stroke();g.fillStyle='#d8ead8';g.beginPath();g.arc(500,300,4,0,Math.PI*2);g.fill();g.strokeRect(45,180,120,240);g.strokeRect(835,180,120,240);g.strokeRect(45,235,48,130);g.strokeRect(907,235,48,130);g.strokeStyle='#e4eee0';g.lineWidth=6;g.strokeRect(25,252,20,96);g.strokeRect(955,252,20,96);g.fillStyle='#c9d8bd';g.beginPath();g.arc(140,300,4,0,7);g.fill();g.beginPath();g.arc(860,300,4,0,7);g.fill();const player=(x,y,color,num,scale=1)=>{g.fillStyle='#09130dcc';g.beginPath();g.ellipse(x,y+15*scale,13*scale,5*scale,0,0,7);g.fill();g.fillStyle=color;g.beginPath();g.arc(x,y,12*scale,0,7);g.fill();g.fillStyle='#f0bd92';g.beginPath();g.arc(x,y-16*scale,7*scale,0,7);g.fill();g.fillStyle='#f7f1df';g.font=`bold ${10*scale}px sans-serif`;g.textAlign='center';g.fillText(num,x,y+4*scale)};for(let i=0;i<6;i++){player(200+((i*137+activeMatch.time*19)%560),105+(i*83)%390,'#ef594a',i+2,.85);player(790-((i*91+activeMatch.time*13)%560),95+(i*97)%410,'#e4e6d8',i+4,.85)}player(activeMatch.x,activeMatch.y,'#f16a4e',10,1.3);g.fillStyle='#f9f5e8';g.beginPath();g.arc(activeMatch.bx,activeMatch.by,8,0,7);g.fill();g.strokeStyle='#252820';g.lineWidth=1;g.stroke();g.restore()}
function holdMove(dir){keysDown[{up:'arrowup',down:'arrowdown',left:'arrowleft',right:'arrowright'}[dir]]=true}function stopMove(){keysDown={}}
function shoot(){if(!activeMatch||activeMatch.done||shotSequence)return;if(!activeMatch.hasBall){activeMatch.log='You need to win possession before you can shoot.';updateMatchHud();return}const match=activeMatch,attacking=match.x>590,near=match.x>790,scoreChance=(attacking?.38:.12)+(near?.29:0)+(s.rating-65)*.008;playShotSequence(match,Math.random()<scoreChance,near)}
function playShotSequence(match,scored,near,corner=false){clearInterval(matchLoop);matchLoop=null;const wrap=document.querySelector('.pitch-wrap');if(!wrap)return;wrap.insertAdjacentHTML('beforeend',`<div class="shot-overlay" role="status" aria-live="polite"><div class="shot-topline"><span>SHOT SEQUENCE</span><button onclick="skipShotSequence()" aria-label="Skip shot animation">SKIP&nbsp;›</button></div><div class="shot-stage ${scored?'shot-goal':'shot-save'}"><div class="shot-stands">TOUCHLINE&nbsp; · &nbsp;MATCHDAY</div><div class="shot-goalframe"><div class="shot-net"></div><div class="shot-keeper">🧤</div></div><div class="shot-pitch"></div><div class="shot-player"><i class="shot-head"></i><i class="shot-body"></i><i class="shot-leg"></i></div><div class="shot-ball">⚽</div><div class="shot-flash">✦</div></div><div class="shot-callout">TAKING THE SHOT…</div></div>`);shotSequence={match,scored,near,corner,timer:setTimeout(()=>{if(!shotSequence)return;const overlay=document.querySelector('.shot-overlay'),callout=overlay?.querySelector('.shot-callout');if(callout)callout.textContent=scored?'GOAL!':near?'SAVED!':'SHOT BLOCKED';overlay?.classList.add('shot-result');shotSequence.timer=setTimeout(finishShotSequence,850)},1150)}}
function skipShotSequence(){finishShotSequence()}
function finishShotSequence(){if(!shotSequence)return;clearTimeout(shotSequence.timer);const {match,scored,near}=shotSequence;shotSequence=null;document.querySelector('.shot-overlay')?.remove();if(activeMatch!==match)return;if(scored){match.home++;s.goals++;match.log='GOAL! A brilliant finish sends the home crowd wild!';match.x=360;match.y=300;match.hasBall=false;match.bx=500;match.by=300;const status=document.getElementById('matchStatus');if(status)status.textContent='GOAL — WHAT A MOMENT!'}else{match.log=near?'Saved! The keeper makes a big stop.':'Shot blocked. The defense scrambles it clear.';match.hasBall=false;match.bx=Math.max(150,match.x-80);match.by=match.y+(Math.random()*100-50);const status=document.getElementById('matchStatus');if(status)status.textContent='Chance created — keep pushing'}match.time+=1;updateMatchHud();drawPitch();if(match.time>=9)endMatch();else startMatchLoop()}
function passBall(){if(!activeMatch||activeMatch.done)return;if(activeMatch.hasBall){activeMatch.x=Math.min(850,activeMatch.x+75);activeMatch.y=Math.max(90,Math.min(510,activeMatch.y+(Math.random()*100-50)));activeMatch.bx=activeMatch.x+15;activeMatch.by=activeMatch.y;activeMatch.log='A crisp pass finds you in space. Great team play!';activeMatch.time+=1}else{activeMatch.hasBall=true;activeMatch.x=activeMatch.bx+20;activeMatch.y=activeMatch.by;activeMatch.log='You read the play and intercept. Now drive forward!';}updateMatchHud();drawPitch();if(activeMatch.time>=9)endMatch()}
function tackle(){if(!activeMatch||activeMatch.done)return;if(!activeMatch.hasBall){activeMatch.hasBall=Math.random()<.78;activeMatch.x=activeMatch.bx+15;activeMatch.y=activeMatch.by;activeMatch.log=activeMatch.hasBall?'Clean tackle! You win possession.':'They evade the challenge — track back!';}else{activeMatch.log='You shield the ball and stay on your feet.'}s.energy=Math.max(10,s.energy-1);updateMatchHud();drawPitch()}
function updateMatchHud(){if(!activeMatch)return;let a=document.getElementById('scoreboard'),m=document.getElementById('minute'),l=document.getElementById('matchLog');if(a)a.innerHTML=`${activeMatch.homeName} &nbsp; ${activeMatch.home} — ${activeMatch.away} &nbsp; ${activeMatch.awayName}`;if(m)m.textContent=`${Math.min(90,activeMatch.time*10+1)}′`;if(l)l.textContent=activeMatch.log;drawPitch()}
function endMatch(){if(!activeMatch||activeMatch.done)return;activeMatch.done=true;clearInterval(matchLoop);const outcome=activeMatch.home>activeMatch.away?'Win':activeMatch.home===activeMatch.away?'Draw':'Loss';if(activeMatch.home===activeMatch.away&&Math.random()<.28){activeMatch.home++;s.goals++;activeMatch.log='A late winner! Your team finds the breakthrough in stoppage time.'}if(activeMatch.home>activeMatch.away){s.wins++;s.streak++}else{s.streak=0}let final=activeMatch.home>activeMatch.away?'Win':activeMatch.home===activeMatch.away?'Draw':'Loss';s.played++;s.energy=Math.max(12,s.energy-17);s.fitness=Math.max(20,s.fitness-6);s.money+=s.salary;let bonus=final==='Win'?900:final==='Draw'?350:120;s.money+=bonus;s.contract=Math.max(0,s.contract-1);s.week++;s.age=s.week%52===0?s.age+1:s.age;s.lastResults=[final[0],...(s.lastResults||[])].slice(0,5);s.lastResult=`${final} · ${activeMatch.home}–${activeMatch.away} · ${money(s.salary)} wages paid`;if(s.played%10===0)s.season++;save();const status=document.getElementById('matchStatus');if(status)status.textContent=`FULL TIME — ${final.toUpperCase()} · +${money(s.salary+bonus)}`;const cont=document.getElementById('continueBtn');if(cont)cont.classList.remove('hidden');document.querySelectorAll('.controls button').forEach(b=>b.disabled=true);const compLabel=document.getElementById('compLabel');if(compLabel)compLabel.textContent=`${activeMatch.competition.toUpperCase()} · FULL TIME`;updateMatchHud()}
function finishMatch(){activeMatch=null;window.onkeydown=null;window.onkeyup=null;go('home');notify('Matchday rewards added to your balance')}
function forfeitMatch(){if(activeMatch&&!activeMatch.done){activeMatch.home=0;activeMatch.away=1;activeMatch.log='You left the match early.';endMatch()}else finishMatch()}
function renderLife(){shell(`<section class="page-head"><div><div class="eyebrow">OFF THE PITCH</div><h1>Life between games</h1><p>Look after your body, make memories, and decide how you spend your free time.</p></div><div class="week-pill">ENERGY <b>${s.energy}%</b></div></section><section class="life-grid"><article class="card life-card"><div class="eyebrow">PERFORMANCE</div><div class="bigicon">🏋️</div><h3>Pro training</h3><p>Push your limits. Improve fitness and earn a small rating boost, but you'll need to recover.</p><button class="btn btn-primary" onclick="gym()">TRAIN · £250</button></article><article class="card life-card"><div class="eyebrow">WELLBEING</div><div class="bigicon">🧘</div><h3>Recovery day</h3><p>Stretch, rest, and reset your energy before the next big match.</p><button class="btn btn-dark" onclick="recover()">REST & RESET</button></article><article class="card life-card"><div class="eyebrow">CONNECTION</div><div class="bigicon">${s.girlfriend?'💞':'☕'}</div><h3>${s.girlfriend?'Date night':'Meet someone'}</h3><p>${s.girlfriend?'Plan a thoughtful evening together and keep your relationship thriving.':'Meet someone new at a local café. Good chemistry takes time.'}</p><button class="btn btn-dark" onclick="dateNight()">${s.girlfriend?'PLAN DATE · £120':'ASK THEM OUT · £80'}</button></article><article class="card life-card"><div class="eyebrow">ENTERTAINMENT</div><div class="bigicon">📺</div><h3>TV & chill</h3><p>Catch the match recap, a funny show, or the latest transfer rumours on Touchline TV.</p><button class="btn btn-dark" onclick="watchTV()">TURN ON TV</button></article><article class="card life-card"><div class="eyebrow">ARCADE</div><div class="bigicon">🎮</div><h3>Play a game</h3><p>Take on a quick penalty shootout. Score three kicks and earn a little fan buzz.</p><button class="btn btn-dark" onclick="arcade()">PENALTY ARCADE</button></article><article class="card life-card"><div class="eyebrow">HIGH RISK · VIRTUAL CREDITS</div><div class="bigicon">🎲</div><h3>Lucky break?</h3><p>Optional fictional coin-flip game. Set a small stake; you can lose it. No real money is involved.</p><button class="btn btn-orange" onclick="casino()">PLAY COIN FLIP</button></article></section><div class="dashboard-bottom"><article class="card news"><div class="cardhead"><h3>Life balance</h3><span class="tiny">YOUR WEEK</span></div><div class="contractline"><span>Fitness</span><strong>${s.fitness}%</strong></div><div class="progress"><i style="width:${s.fitness}%"></i></div><div class="contractline"><span>Energy</span><strong>${s.energy}%</strong></div><div class="progress"><i style="width:${s.energy}%;background:#82c9ed"></i></div></article><article class="card news"><div class="cardhead"><h3>Your story</h3><span class="tiny">CAREER</span></div><div class="newsrow"><span class="newsicon">${s.girlfriend?'💌':'🌱'}</span><div><b>${s.girlfriend?'You are building a life together.':'A good life off the pitch is part of a great career.'}</b><p>${s.played} appearances · ${s.goals} goals · ${s.assists} assists</p></div></div></article></div>`)}
function spend(amount){if(s.money<amount){notify('Not enough in your balance');return false}s.money-=amount;save();return true}function gym(){if(!spend(250))return;s.energy=Math.max(15,s.energy-17);s.fitness=Math.min(100,s.fitness+8);if(Math.random()<.45)s.rating++;save();renderLife();notify('Training complete — fitness +8, energy -17')}function recover(){s.energy=Math.min(100,s.energy+28);s.fitness=Math.min(100,s.fitness+3);save();renderLife();notify('Recovery complete — feeling fresher')}function dateNight(){if(!spend(s.girlfriend?120:80))return;if(!s.girlfriend){s.girlfriend=true;s.lastResult='A new relationship is blossoming alongside your career.';notify('It was a lovely evening. You are officially dating!')}else notify('A lovely evening together — relationship thriving');s.energy=Math.min(100,s.energy+5);save();renderLife()}
function modal(title,body,actions){let root=document.createElement('div');root.className='modal-backdrop';root.innerHTML=`<div class="modal"><h2>${title}</h2>${body}<div class="modal-actions">${actions}</div></div>`;root.addEventListener('click',e=>{if(e.target===root)root.remove()});document.body.appendChild(root);return root}function closeModal(){document.querySelector('.modal-backdrop')?.remove()}
function watchTV(){modal('Touchline TV',`<p>What are you watching tonight?</p><div class="life-grid" style="grid-template-columns:1fr 1fr"><button class="btn btn-dark" onclick="tvPick('Match of the day')">⚽ Match of the day</button><button class="btn btn-dark" onclick="tvPick('Transfer centre')">📰 Transfer centre</button><button class="btn btn-dark" onclick="tvPick('Comedy hour')">😄 Comedy hour</button><button class="btn btn-dark" onclick="tvPick('Nature live')">🌿 Nature live</button></div><p id="tvText">Choose a channel. Your energy gets a small boost while you unwind.</p>`,'<button class="btn btn-dark" onclick="closeModal()">CLOSE</button>')}function tvPick(which){s.energy=Math.min(100,s.energy+7);save();document.getElementById('tvText').textContent=`Now watching ${which}. That was a nice way to unwind — energy +7.`;notify('Energy +7 from some downtime')}
let penaltyTurn=0,penaltyGoals=0;function arcade(){penaltyTurn=0;penaltyGoals=0;penaltyRound()}function penaltyRound(){if(penaltyTurn>=3){let win=penaltyGoals>=2;if(win){s.money+=300;s.fans=(s.fans||0)+20;save()}modal(win?'Top bins!': 'Good effort!',`<p>You scored ${penaltyGoals} of 3 penalties. ${win?'A £300 arcade prize is yours!':'Practice makes perfect. Come back for another go.'}</p>`,`<button class="btn btn-primary" onclick="closeModal();renderLife()">DONE</button>`);return}let target=['left','middle','right'][Math.floor(Math.random()*3)];modal(`Penalty ${penaltyTurn+1} of 3`,`<p>Pick a corner. The keeper is watching carefully.</p><div class="controls"><button class="btn btn-dark" onclick="kickPenalty('left','${target}')">↖ LEFT</button><button class="btn btn-dark" onclick="kickPenalty('middle','${target}')">↑ MIDDLE</button><button class="btn btn-dark" onclick="kickPenalty('right','${target}')">↗ RIGHT</button></div><p id="penaltyResult"></p>`,'<button class="btn btn-dark" onclick="closeModal()">QUIT</button>')}function kickPenalty(pick,target){const scored=pick!==target;penaltyTurn++;if(scored)penaltyGoals++;closeModal();let m=modal(scored?'GOAL! ⚽':'SAVED! 🧤',`<p>${scored?'You picked the perfect spot.':'The keeper guessed correctly.'} Score: ${penaltyGoals}/${penaltyTurn}</p>`,'<button class="btn btn-primary" onclick="closeModal();penaltyRound()">NEXT →</button>')}
function casino(){if(s.money<100){notify('You need at least £100 to play');return}modal('Coin flip',`<p>Purely fictional in-game credits. Choose your stake carefully; the game can take your stake or double it.</p><label style="font-size:11px">STAKE: <b id="stakeValue">£100</b></label><input id="stake" class="range" type="range" min="100" max="${Math.min(2000,s.money)}" step="100" value="100" oninput="document.getElementById('stakeValue').textContent='£'+this.value">`,'<button class="btn btn-dark" onclick="closeModal()">WALK AWAY</button><button class="btn btn-orange" onclick="flipCoin()">FLIP COIN</button>')}function flipCoin(){let stake=Number(document.getElementById('stake')?.value||100);if(!spend(stake)){closeModal();return}s.casinoPlays++;let win=Math.random()<.48;if(win)s.money+=stake*2;save();closeModal();notify(win?`Heads! You won ${money(stake)}.`:`Tails — you lost ${money(stake)}.`);renderLife()}
let clubhouseTab='transfers';function clubTab(tab){clubhouseTab=tab;renderClubhouse(tab)}function renderClubhouse(tab='transfers'){clubhouseTab=tab;const tabs=[['transfers','Transfer market'],['mall','The mall'],['hair','Style studio']];let content='';if(tab==='transfers'){content=`<div class="toolbar"><div><b style="font-size:12px">Find your next chapter</b><div class="tiny" style="margin-top:5px">Offers are for your player. Weekly wages arrive after each match.</div></div><span class="tiny">${s.league}</span></div><div class="club-grid">${clubs.map(c=>{let req=c.level*13+2,ok=s.rating>=req||c.name===s.club;return `<article class="card club-option ${c.name===s.club?'selected':''}"><div class="clubcrest" style="background:linear-gradient(145deg,${c.color},#252b22)">${c.short.slice(0,2)}</div><strong>${c.name}${c.name===s.club?' · CURRENT':''}</strong><small>${c.league} · ${c.level}★</small><div class="offer">${money(c.salary)} / week</div><button class="btn ${ok?'btn-primary':'btn-dark'}" style="width:100%;margin-top:10px" ${ok?'':'disabled'} onclick="signWith('${c.name}')">${c.name===s.club?'SIGNED':'ACCEPT OFFER'}</button>${ok?'':`<small style="color:var(--orange)">Needs ${req} OVR</small>`}</article>`}).join('')}</div>`}else if(tab==='mall'){const items=[['Away Day Hoodie','🧥',680,'Streetwear'],['Neon Training Top','👕',520,'Performance'],['City Runner Sneakers','👟',890,'Footwear'],['Matchday Jacket','🧢',740,'Outerwear'],['Vintage Club Scarf','🧣',260,'Accessories'],['Lime Boot Collection','🥾',1100,'Footwear']];content=`<div class="toolbar"><div><b style="font-size:12px">Wear it your way</b><div class="tiny" style="margin-top:5px">Buy a look and wear it on your player profile.</div></div><span class="money">◈ ${money(s.money)}</span></div><div class="shop-grid">${items.map(([name,icon,price,category])=>{let owned=s.wardrobe.includes(name),worn=s.outfit===name;return `<article class="card item-card"><div class="item-preview">${icon}</div><h3>${name}</h3><p>${category} · ${worn?'NOW WEARING':owned?'IN YOUR WARDROBE':money(price)}</p><button class="btn ${worn?'btn-dark':'btn-primary'}" onclick="${owned?`wear('${name}')`:`buyClothes('${name}',${price})`}">${worn?'WORN':owned?'WEAR IT':'BUY ITEM'}</button></article>`}).join('')}</div>`}else{const styles=['Short fade','Curly crop','Slick back','Buzz cut','Long waves','Braided'];content=`<div class="toolbar"><div><b style="font-size:12px">Fresh cut, fresh start</b><div class="tiny" style="margin-top:5px">Try a new hairstyle for £180. Your choice is saved to your look.</div></div><span class="tiny">CURRENT: ${s.hair}</span></div><div class="hair-row">${styles.map((h,i)=>`<button class="hair-choice ${s.hair===h?'selected':''}" onclick="chooseHair('${h}')"><span style="font-size:23px">${['✂️','🌀','💈','🪒','〰️','〽️'][i]}</span><br><span style="font-size:10px">${h}</span></button>`).join('')}</div><div class="card panel" style="margin-top:17px"><div class="player-figure" style="margin:auto;height:220px"><div class="hair"></div><div class="head"></div><div class="body"></div><div class="shirtline"></div><div class="number">10</div><div class="shorts"></div><div class="leg l"></div><div class="leg r"></div><div class="sock l"></div><div class="sock r"></div><div class="boot l"></div><div class="boot r"></div></div></div>`}shell(`<section class="page-head"><div><div class="eyebrow">YOUR CAREER · YOUR CALL</div><h1>Clubhouse</h1><p>Build your future, find your look, and make the club feel like home.</p></div><div class="week-pill">WEEKLY WAGE <b>${money(s.salary)}</b></div></section><div class="subtabs">${tabs.map(([id,n])=>`<button class="${tab===id?'active':''}" onclick="clubTab('${id}')">${n}</button>`).join('')}</div><section class="card panel">${content}</section>`)}function signWith(name){let c=clubs.find(x=>x.name===name);if(!c)return;if(s.rating<c.level*13+2){notify('Keep improving your rating to unlock this offer');return}if(name===s.club){notify('You already play here');return}modal('New contract offer',`<p><b>${c.name}</b> want you on their team in the ${c.league}. The contract offers <b>${money(c.salary)} each week</b> for 24 weeks. Sign and move clubs?</p><p>Current wage: ${money(s.salary)} weekly.</p>`,`<button class="btn btn-dark" onclick="closeModal()">NOT NOW</button><button class="btn btn-primary" onclick="acceptTransfer('${name}')">SIGN CONTRACT</button>`)}function acceptTransfer(name){const c=clubs.find(x=>x.name===name);if(!c)return;s.club=c.name;s.salary=c.salary;s.league=c.league;s.contract=24;s.energy=Math.max(s.energy,65);save();closeModal();renderClubhouse('transfers');notify(`Welcome to ${c.name}! New wage: ${money(c.salary)} / week`)}function buyClothes(name,price){if(!spend(price))return;s.wardrobe.push(name);s.outfit=name;save();renderClubhouse('mall');notify(`${name} added to your wardrobe and worn`)}function wear(name){s.outfit=name;save();renderClubhouse('mall');notify(`Now wearing ${name}`)}function chooseHair(name){if(name===s.hair){notify('That style is already yours');return}if(!spend(180))return;s.hair=name;save();renderClubhouse('hair');notify(`Fresh cut: ${name}`)}
function renderProfile(){shell(`<section class="page-head"><div><div class="eyebrow">PLAYER PROFILE · SEASON ${s.season}</div><h1>${escapeHTML(s.name)}</h1><p>Every career has a story. This one is yours.</p></div><button class="btn btn-dark" onclick="modal('Start a new save?', '<p>This will erase your current player and career from this browser.</p>', '<button class=\'btn btn-dark\' onclick=\'closeModal()\'>KEEP CAREER</button><button class=\'btn btn-orange\' onclick=\'resetCareer()\'>RESET SAVE</button>')">RESET CAREER</button></section><div class="dashboard-bottom"><article class="card panel"><div class="cardhead"><h3>Player information</h3><span class="tiny">${s.nation}</span></div><div class="contractline"><span>Club</span><strong>${s.club}</strong></div><div class="contractline"><span>Position</span><strong>Attacking midfielder · #10</strong></div><div class="contractline"><span>Age</span><strong>${s.age}</strong></div><div class="contractline"><span>Style</span><strong>${s.hair} · ${s.outfit}</strong></div><div class="contractline"><span>Relationship</span><strong>${s.girlfriend?'In a relationship':'Single'}</strong></div></article><article class="card panel"><div class="cardhead"><h3>Career statistics</h3><span class="tiny">ALL TIME</span></div><div class="contractline"><span>Overall rating</span><strong>${s.rating} OVR</strong></div><div class="contractline"><span>Appearances</span><strong>${s.played}</strong></div><div class="contractline"><span>Goals</span><strong>${s.goals}</strong></div><div class="contractline"><span>Assists</span><strong>${s.assists}</strong></div><div class="contractline"><span>Club wins</span><strong>${s.wins}</strong></div><div class="contractline"><span>Weekly wage</span><strong>${money(s.salary)}</strong></div></article></div><article class="card panel" style="margin-top:14px"><div class="cardhead"><h3>National journey</h3><span class="tiny">${s.nation.toUpperCase()}</span></div><p style="font-size:11px;color:var(--muted);line-height:1.6">Represent ${s.nation} in the World Cup from Matchday. Make the national squad proud — every international highlight adds to your legacy.</p><button class="btn btn-primary" onclick="go('match');setTimeout(()=>{let b=[...document.querySelectorAll('.subtabs button')].find(x=>x.textContent==='World Cup');if(b)b.click()},80)">PLAY WORLD CUP →</button></article>`)}function resetCareer(){localStorage.removeItem('touchline-save');s={...initial};closeModal();renderCreate();notify('A fresh career awaits')}
/* Swipe-first 3D match engine */
const scenarioLanes=[
 {name:'Central midfield',x:535,y:300,hasBall:true},
 {name:'Right channel',x:665,y:190,hasBall:true},
 {name:'Left channel',x:665,y:420,hasBall:true},
 {name:'Edge of the box',x:815,y:300,hasBall:true},
 {name:'Loose-ball press',x:575,y:300,hasBall:false}
];
const scenarioStates=[
 {name:'Fresh start',time:0,home:0,away:0},
 {name:'Chasing the game',time:9,home:0,away:1},
 {name:'Level at the break',time:18,home:1,away:1},
 {name:'Late pressure',time:29,home:0,away:1},
 {name:'Final minutes',time:38,home:1,away:1}
];
const scenarioChallenges=[
 {title:'Find the far corner',objective:'Score by swiping into either far corner of the goal.',type:'corner'},
 {title:'Win it back',objective:'Recover possession from the loose ball.',type:'recover'},
 {title:'Link-up play',objective:'Complete a pass to open the attack.',type:'pass'},
 {title:'Drive into the box',objective:'Carry the ball into the attacking area.',type:'advance'},
 {title:'Make your mark',objective:'Take at least one shot on goal.',type:'shoot'},
 {title:'Take the lead',objective:'Finish the match ahead on the scoreboard.',type:'win'},
 {title:'Keep the keeper busy',objective:'Take two shots before full time.',type:'twoShots'},
 {title:'Clinical finish',objective:'Score twice in this highlight.',type:'brace'},
 {title:'Hold your nerve',objective:'Avoid defeat before the final whistle.',type:'survive'}
];
const playableScenarios=scenarioLanes.flatMap((lane,li)=>scenarioStates.flatMap((state,si)=>scenarioChallenges.map((challenge,ci)=>({
 id:li*scenarioStates.length*scenarioChallenges.length+si*scenarioChallenges.length+ci+1,
 lane,state,challenge,name:`${lane.name} · ${state.name} · ${challenge.title}`,
 x:lane.x,y:lane.y,hasBall:lane.hasBall,bx:lane.hasBall?lane.x:lane.x-35,by:lane.y,
 time:state.time,home:state.home,away:state.away
}))));
let activeScenario=playableScenarios[0];
function scenarioOptionsHTML(){return playableScenarios.map(v=>`<option value="${v.id}"${v.id===activeScenario.id?' selected':''}>${String(v.id).padStart(3,'0')} · ${v.name}</option>`).join('')}
function previewScenario(id){const next=playableScenarios.find(v=>v.id===Number(id));if(!next)return;const name=document.getElementById('scenarioName'),goal=document.getElementById('scenarioObjective');if(name)name.textContent=`READY · SCENARIO ${String(next.id).padStart(3,'0')} / ${playableScenarios.length} · ${next.name}`;if(goal)goal.textContent=next.challenge.objective}
function applyScenario(id,announce=true){const next=playableScenarios.find(v=>v.id===Number(id));if(!next||!activeMatch)return;clearInterval(matchLoop);if(shotSequence){clearTimeout(shotSequence.timer);shotSequence=null;document.querySelector('.shot-overlay')?.remove()}activeScenario=next;activeMatch={time:next.time,home:next.home,away:next.away,x:next.x,y:next.y,maxX:next.x,advancedWithBall:next.hasBall&&next.x>=760,bx:next.bx,by:next.by,hasBall:next.hasBall,done:false,competition:activeMatch.competition||'League',homeName:activeMatch.homeName||club().short,awayName:activeMatch.awayName||'ROV',log:announce?`Scenario ${next.id} loaded: ${next.name}. ${next.challenge.objective}`:`${next.name}. ${next.challenge.objective}`,aim:null,scenarioStats:{shots:0,onTarget:0,cornerAttempts:0,passes:0,recoveries:0,goals:0,cornerGoals:0},opponents:Array.from({length:8},(_,i)=>({x:540+i%4*90,y:100+Math.floor(i/4)*340+i%3*55}))};let select=document.getElementById('scenarioSelect'),name=document.getElementById('scenarioName'),goal=document.getElementById('scenarioObjective');if(select)select.value=String(next.id);if(name)name.textContent=`SCENARIO ${String(next.id).padStart(3,'0')} / ${playableScenarios.length} · ${next.name}`;if(goal)goal.textContent=next.challenge.objective;document.querySelectorAll('.controls button').forEach(b=>b.disabled=false);let status=document.getElementById('matchStatus');if(status)status.textContent='SCENARIO READY — MAKE YOUR MOMENT';let continueBtn=document.getElementById('continueBtn');if(continueBtn)continueBtn.classList.add('hidden');updateMatchHud();startMatchLoop()}
let matchGesture=null;
function renderMatch(){activeMatch={time:activeScenario.time,home:activeScenario.home,away:activeScenario.away,x:activeScenario.x,y:activeScenario.y,maxX:activeScenario.x,advancedWithBall:activeScenario.hasBall&&activeScenario.x>=760,bx:activeScenario.bx,by:activeScenario.by,hasBall:activeScenario.hasBall,done:false,competition:'League',homeName:club().short,awayName:'ROV',log:`${activeScenario.name}. ${activeScenario.challenge.objective}`,aim:null,scenarioStats:{shots:0,onTarget:0,cornerAttempts:0,passes:0,recoveries:0,goals:0,cornerGoals:0},opponents:Array.from({length:8},(_,i)=>({x:540+i%4*90,y:100+Math.floor(i/4)*340+i%3*55}))};shell(`<section class="page-head"><div><div class="eyebrow">MATCHDAY ${s.played+1} · ${s.club.toUpperCase()}</div><h1>Own the pitch</h1><p>Drag to move. With the ball, swipe from your player toward the spot you want to hit.</p></div><div class="week-pill">FITNESS <b>${s.fitness}%</b></div></section><div class="toolbar"><div class="subtabs"><button class="active" onclick="setCompetition('League',this)">League</button><button onclick="setCompetition('UEFA Champions League',this)">UEFA Champions League</button><button onclick="setCompetition('World Cup',this)">World Cup</button></div><span class="tiny">DRAG TO MOVE · SWIPE FROM PLAYER TO SHOOT</span></div><section class="scenario-picker"><label for="scenarioSelect">PLAYABLE SCENARIOS <b>${playableScenarios.length}</b><select id="scenarioSelect" onchange="previewScenario(this.value)">${scenarioOptionsHTML()}</select></label><button class="btn btn-dark" onclick="applyScenario(document.getElementById('scenarioSelect').value)">LOAD SCENARIO</button><button class="btn btn-primary" onclick="applyScenario(1+Math.floor(Math.random()*${playableScenarios.length}))">RANDOM</button><span class="scenario-caption" id="scenarioName">SCENARIO ${String(activeScenario.id).padStart(3,'0')} / ${playableScenarios.length} · ${activeScenario.name}</span></section><section class="match-layout"><div class="pitch-wrap pitch-3d"><canvas id="pitch" aria-label="3D football pitch. Swipe from your player toward your target to shoot."></canvas><div class="match-overlay"><div class="scoreboard"><b id="scoreboard">${club().short} &nbsp; 0 — 0 &nbsp; ROV</b><span id="compLabel">LEAGUE · 1ST HALF</span></div><div class="minute" id="minute">01′</div></div><div class="swipe-tip" id="swipeTip">Ball at your feet · swipe toward goal</div></div><aside class="match-side"><div class="sidebox"><h3>Swipe controls</h3><p>Drag on the pitch to move. With the ball, start near your player and swipe toward your target in the goal.</p><div class="match-action-row"><button class="btn btn-primary" onclick="shoot()">⚽ &nbsp; SHOOT</button><button class="btn btn-dark" onclick="passBall()">↗ &nbsp; PASS</button><button class="btn btn-orange" onclick="tackle()">✦ &nbsp; TACKLE</button></div><p class="mobile-note">Desktop: click-drag to move or aim. WASD / arrows also move.</p></div><div class="sidebox scenario-goal"><h3>SCENARIO OBJECTIVE</h3><p id="scenarioObjective">${activeScenario.challenge.objective}</p></div><div class="sidebox"><h3>Match highlights</h3><p id="matchLog">${activeMatch.log}</p><div class="match-status" id="matchStatus">Ready for kickoff</div><div class="end-actions"><button class="btn btn-dark" onclick="forfeitMatch()">Leave match</button><button class="btn btn-primary hidden" id="continueBtn" onclick="finishMatch()">FULL TIME →</button></div></div></aside></section>`);initPitch();window.onkeydown=e=>{let k=e.key.toLowerCase();keysDown[k]=true;if(k===' '){e.preventDefault();shoot()}if(k==='e')passBall();if(k==='shift')tackle()};window.onkeyup=e=>keysDown[e.key.toLowerCase()]=false;startMatchLoop()}
function projectPitch(x,y){let z=.58+.42*y/600;return{x:500+(x-500)*z,y:74+y*.78,scale:z}}
function unprojectPitch(x,y){let yy=Math.max(0,Math.min(600,(y-74)/.78)),z=.58+.42*yy/600;return{x:Math.max(0,Math.min(1000,500+(x-500)/z)),y:yy}}
function initPitch(){let c=document.getElementById('pitch');if(!c)return;let resize=()=>{let r=c.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);c.width=r.width*d;c.height=r.height*d;drawPitch()};new ResizeObserver(resize).observe(c);resize();c.addEventListener('pointerdown',matchPointerDown);c.addEventListener('pointermove',matchPointerMove);c.addEventListener('pointerup',matchPointerUp);c.addEventListener('pointercancel',matchPointerUp)}
function canvasPoint(e){let r=e.currentTarget.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width*1000,y:(e.clientY-r.top)/r.height*600}}
function matchPointerDown(e){if(!activeMatch||activeMatch.done)return;e.preventDefault();e.currentTarget.setPointerCapture(e.pointerId);let p=canvasPoint(e),me=projectPitch(activeMatch.x,activeMatch.y);matchGesture={start:p,last:p,mode:activeMatch.hasBall&&Math.hypot(p.x-me.x,p.y-me.y)<85?'aim':'move'};if(matchGesture.mode==='aim')activeMatch.aim=p;else movePlayerTo(unprojectPitch(p.x,p.y),false);drawPitch()}
function matchPointerMove(e){if(!matchGesture||!activeMatch)return;let p=canvasPoint(e);matchGesture.last=p;if(matchGesture.mode==='aim'){activeMatch.aim=p;drawPitch()}else movePlayerTo(unprojectPitch(p.x,p.y),false)}
function matchPointerUp(e){if(!matchGesture||!activeMatch)return;let q=matchGesture;matchGesture=null;if(q.mode==='aim'){let p=canvasPoint(e);activeMatch.aim=null;if(Math.hypot(p.x-q.start.x,p.y-q.start.y)>24)takeAimedShot(unprojectPitch(p.x,p.y))}else movePlayerTo(unprojectPitch(q.last.x,q.last.y),true);drawPitch()}
function movePlayerTo(p,log=true){if(!activeMatch||activeMatch.done)return;activeMatch.x=Math.max(35,Math.min(965,p.x));activeMatch.y=Math.max(35,Math.min(565,p.y));activeMatch.maxX=Math.max(activeMatch.maxX||activeMatch.x,activeMatch.x);if(activeMatch.hasBall){activeMatch.bx=activeMatch.x;activeMatch.by=activeMatch.y;activeMatch.maxX=Math.max(activeMatch.maxX||activeMatch.x,activeMatch.x);if(activeMatch.x>=760)activeMatch.advancedWithBall=true}else if(Math.hypot(activeMatch.x-activeMatch.bx,activeMatch.y-activeMatch.by)<100){activeMatch.hasBall=true;activeMatch.x=activeMatch.bx;activeMatch.y=activeMatch.by;activeMatch.maxX=Math.max(activeMatch.maxX||activeMatch.x,activeMatch.x);if(activeMatch.x>=760)activeMatch.advancedWithBall=true;activeMatch.scenarioStats.recoveries++;activeMatch.log='You collect the loose ball. Drive forward!'}else if(log)activeMatch.log='You move into space. Get close to the ball to take possession.';if(log)updateMatchHud();else drawPitch()}
function startMatchLoop(){clearInterval(matchLoop);matchLoop=setInterval(()=>{if(!activeMatch||activeMatch.done)return;activeMatch.time++;activeMatch.opponents=(activeMatch.opponents||Array.from({length:8},(_,i)=>({x:540+i%4*90,y:100+Math.floor(i/4)*340+i%3*55}))).map(p=>({x:Math.max(380,Math.min(950,p.x+(Math.random()-.45)*22)),y:Math.max(40,Math.min(560,p.y+(Math.random()-.5)*24))}));if(activeScenario.challenge.type==='advance'&&activeMatch.advancedWithBall)activeMatch.log='Challenge complete: you drove into the box!';if(activeMatch.time>=45)endMatch();updateMatchHud()},1000)}
function drawPitch(){let c=document.getElementById('pitch');if(!c||!activeMatch)return;let g=c.getContext('2d'),w=c.width,h=c.height;g.clearRect(0,0,w,h);g.save();g.scale(w/1000,h/600);let sky=g.createLinearGradient(0,0,0,210);sky.addColorStop(0,'#101c24');sky.addColorStop(1,'#47636a');g.fillStyle=sky;g.fillRect(0,0,1000,600);for(let i=0;i<32;i++){g.fillStyle=i%3?'#d9e8d066':'#f3edc899';g.beginPath();g.arc(18+i*31,95+i%4*12,2+i%3,0,7);g.fill()}
const P=(x,y)=>projectPitch(x,y);function poly(ps,fill,stroke){g.beginPath();ps.map(p=>P(...p)).forEach((p,i)=>i?g.lineTo(p.x,p.y):g.moveTo(p.x,p.y));g.closePath();if(fill){g.fillStyle=fill;g.fill()}if(stroke){g.strokeStyle=stroke;g.lineWidth=2;g.stroke()}}poly([[0,0],[1000,0],[1000,600],[0,600]],'#153922');for(let i=0;i<10;i++)poly([[i*100,0],[i*100+100,0],[i*100+100,600],[i*100,600]],i%2?'#28683c':'#225c34');const line=ps=>{g.beginPath();ps.map(p=>P(...p)).forEach((p,i)=>i?g.lineTo(p.x,p.y):g.moveTo(p.x,p.y));g.strokeStyle='#e7f2dcaa';g.lineWidth=2;g.stroke()};line([[0,0],[1000,0],[1000,600],[0,600],[0,0]]);line([[500,0],[500,600]]);line([[0,180],[165,180],[165,420],[0,420]]);line([[1000,180],[835,180],[835,420],[1000,420]]);line([[0,235],[55,235],[55,365],[0,365]]);line([[1000,235],[945,235],[945,365],[1000,365]]);let cc=P(500,300),cx=P(590,300),cy=P(500,390);g.beginPath();g.ellipse(cc.x,cc.y,Math.abs(cx.x-cc.x),Math.abs(cy.y-cc.y),0,0,7);g.stroke();
function goal(x,d){let a=P(x,235),b=P(x,365),z=d*34;g.strokeStyle='#f7f3e7';g.lineWidth=4;g.beginPath();g.moveTo(a.x,a.y);g.lineTo(a.x+z,a.y-10);g.lineTo(b.x+z,b.y+10);g.lineTo(b.x,b.y);g.stroke();g.strokeStyle='#ffffff55';g.lineWidth=1;for(let i=0;i<5;i++){g.beginPath();g.moveTo(a.x+z*i/4,a.y);g.lineTo(b.x+z*i/4,b.y);g.stroke()}}goal(1000,1);goal(0,-1);
function player(x,y,color,n,user=false){let p=P(x,y),r=11*p.scale;g.fillStyle='#06120bc9';g.beginPath();g.ellipse(p.x,p.y+5*p.scale,r*1.25,r*.42,0,0,7);g.fill();g.fillStyle='#111';g.fillRect(p.x-r*.6,p.y,r*.4,r);g.fillRect(p.x+r*.2,p.y,r*.4,r);g.fillStyle=color;g.beginPath();g.ellipse(p.x,p.y-r*.35,r*.82,r,0,0,7);g.fill();g.fillStyle=user?'#c7f36b':'#f1c09a';g.beginPath();g.arc(p.x,p.y-r*1.5,r*.42,0,7);g.fill();g.fillStyle='#fff';g.font=`bold ${Math.max(7,8*p.scale)}px sans-serif`;g.textAlign='center';g.fillText(n,p.x,p.y+r*.1);if(user){g.strokeStyle='#e3ff9a';g.lineWidth=2;g.beginPath();g.ellipse(p.x,p.y-r*.3,r*1.35,r*1.6,0,0,7);g.stroke()}}
(activeMatch.opponents||[]).slice().sort((a,b)=>a.y-b.y).forEach((p,i)=>player(p.x,p.y,'#e7e5d7',i+2));player(970,300,'#e4e6d8','GK');player(activeMatch.x,activeMatch.y,'#f16a4e',10,true);let b=P(activeMatch.bx,activeMatch.by);g.fillStyle='#fff';g.beginPath();g.arc(b.x,b.y,6*b.scale,0,7);g.fill();g.strokeStyle='#20251d';g.stroke();if(activeMatch.aim){let p=P(activeMatch.x,activeMatch.y);g.strokeStyle='#d9ff84';g.lineWidth=3;g.setLineDash([8,6]);g.beginPath();g.moveTo(p.x,p.y-8);g.lineTo(activeMatch.aim.x,activeMatch.aim.y);g.stroke();g.setLineDash([]);g.beginPath();g.arc(activeMatch.aim.x,activeMatch.aim.y,13,0,7);g.stroke()}g.restore()}
function holdMove(dir){keysDown[{up:'arrowup',down:'arrowdown',left:'arrowleft',right:'arrowright'}[dir]]=true}function stopMove(){keysDown={}}
function takeAimedShot(target){if(!activeMatch||activeMatch.done||shotSequence)return;if(!activeMatch.hasBall){activeMatch.log='Win possession first. Drag close to the ball.';updateMatchHud();return}if(target.x-activeMatch.x<20){activeMatch.log='Swipe toward the goal on the right side.';updateMatchHud();return}const match=activeMatch,dx=target.x-match.x,landingY=match.y+(target.y-match.y)*(1000-match.x)/dx,onTarget=landingY>=235&&landingY<=365,corner=onTarget&&(landingY<=255||landingY>=345),distance=Math.hypot(1000-match.x,landingY-match.y),precision=Math.max(0,1-Math.abs(landingY-300)/90),chance=Math.max(.12,Math.min(.88,.25+(s.rating-60)*.012+precision*.34-(1000-match.x)*.00048));match.scenarioStats.shots++;if(onTarget)match.scenarioStats.onTarget++;if(corner)match.scenarioStats.cornerAttempts++;const outcome=onTarget&&Math.random()<chance;playShotSequence(match,outcome,onTarget,corner,landingY)}function shoot(){if(activeMatch)takeAimedShot({x:1000,y:300+(Math.random()-.5)*60})}
function passBall(){if(!activeMatch||activeMatch.done)return;if(!activeMatch.hasBall){activeMatch.log='Move close to the ball to collect it.';updateMatchHud();return}activeMatch.scenarioStats.passes++;activeMatch.x=Math.min(900,activeMatch.x+90);activeMatch.maxX=Math.max(activeMatch.maxX||activeMatch.x,activeMatch.x);if(activeMatch.x>=760)activeMatch.advancedWithBall=true;activeMatch.y=Math.max(45,Math.min(555,activeMatch.y+(Math.random()-.5)*90));activeMatch.bx=activeMatch.x;activeMatch.by=activeMatch.y;activeMatch.log='A sharp one-two opens the right channel. Keep driving!';updateMatchHud()}function tackle(){if(!activeMatch||activeMatch.done)return;if(!activeMatch.hasBall){activeMatch.hasBall=true;activeMatch.x=activeMatch.bx;activeMatch.y=activeMatch.by;if(activeMatch.x>=760)activeMatch.advancedWithBall=true;activeMatch.scenarioStats.recoveries++;activeMatch.log='Clean challenge! You win the ball.'}else activeMatch.log='You shield possession and keep the move alive.';s.energy=Math.max(10,s.energy-1);updateMatchHud()}function playMoment(){if(!activeMatch||activeMatch.done)return;activeMatch.x=Math.min(850,activeMatch.x+100);activeMatch.y=300;activeMatch.hasBall=true;activeMatch.bx=activeMatch.x;activeMatch.by=300;activeMatch.log='A teammate slips a pass into space. You are through!';updateMatchHud()}
function playShotSequence(match,scored,near,corner=false,landingY=300){clearInterval(matchLoop);matchLoop=null;let wrap=document.querySelector('.pitch-wrap');if(!wrap)return;const vertical=Math.max(-27,Math.min(-9,-27+(landingY-235)/130*18)),keeperY=Math.max(-38,Math.min(38,(landingY-300)/65*34)),style=`--shot-dy:${vertical}vh;--keeper-y:${keeperY}px`;wrap.insertAdjacentHTML('beforeend',`<div class="shot-overlay" role="status" style="${style}"><div class="shot-topline"><span>SHOT SEQUENCE</span><button onclick="skipShotSequence()">SKIP&nbsp;›</button></div><div class="shot-stage ${scored?'shot-goal':'shot-save'}"><div class="shot-stands">TOUCHLINE · MATCHDAY</div><div class="shot-goalframe"><div class="shot-net"></div><div class="shot-keeper">🧤</div></div><div class="shot-pitch"></div><div class="shot-player"><i class="shot-head"></i><i class="shot-body"></i><i class="shot-leg"></i></div><div class="shot-ball">⚽</div><div class="shot-flash">✦</div></div><div class="shot-callout">${near?corner?'AIMING FOR THE CORNER…':'ON TARGET…':'GOING WIDE…'}</div></div>`);shotSequence={match,scored,near,corner,landingY,timer:setTimeout(()=>{if(!shotSequence)return;let o=document.querySelector('.shot-overlay'),t=o?.querySelector('.shot-callout');if(t)t.textContent=scored?'GOAL!':near?'SAVED!':'WIDE!';o?.classList.add('shot-result');shotSequence.timer=setTimeout(finishShotSequence,850)},1050)} }function skipShotSequence(){finishShotSequence()}function finishShotSequence(){if(!shotSequence)return;clearTimeout(shotSequence.timer);let{match,scored,near,corner,landingY}=shotSequence;shotSequence=null;document.querySelector('.shot-overlay')?.remove();if(activeMatch!==match)return;if(scored){match.home++;s.goals++;match.scenarioStats.goals++;if(corner)match.scenarioStats.cornerGoals++;match.log=corner?'GOAL! A perfect swipe into the corner!':'GOAL! A brilliant finish!';match.hasBall=false;match.bx=650;match.by=300}else{match.log=near?'Saved! The keeper reads your shot.':landingY<235?'Too high — the shot sails over.':'Wide of the goal — adjust your swipe!';match.hasBall=false;match.bx=Math.max(150,match.x-100);match.by=match.y+(Math.random()-.5)*100}match.time+=2;updateMatchHud();if(match.time>=45)endMatch();else startMatchLoop()}
function updateMatchHud(){if(!activeMatch)return;let a=document.getElementById('scoreboard'),m=document.getElementById('minute'),l=document.getElementById('matchLog');if(a)a.innerHTML=`${activeMatch.homeName} &nbsp; ${activeMatch.home} — ${activeMatch.away} &nbsp; ${activeMatch.awayName}`;if(m)m.textContent=`${Math.min(90,activeMatch.time*2+1)}′`;if(l)l.textContent=activeMatch.log;let t=document.getElementById('swipeTip');if(t)t.textContent=activeMatch.hasBall?'Ball at your feet · swipe from your player to shoot':'No possession · drag close to the ball';let objective=document.getElementById('scenarioObjective');if(objective)objective.textContent=`${activeScenario.challenge.objective} · ${scenarioProgress(activeMatch.done?activeMatch.home>activeMatch.away?'Win':activeMatch.home===activeMatch.away?'Draw':'Loss':null)}`;drawPitch()}
function setCompetition(c,el){activeMatch.competition=c;if(c==='World Cup'){activeMatch.homeName=s.nation==='England'?'ENG':s.nation.slice(0,3).toUpperCase();activeMatch.awayName='MEX';activeMatch.log=`Represent ${s.nation}. Swipe your way to glory!`}else if(c==='UEFA Champions League'){activeMatch.homeName=club().short;activeMatch.awayName='PAR';activeMatch.log='Champions League night! Make your mark on Europe.'}else{activeMatch.homeName=club().short;activeMatch.awayName='ROV';activeMatch.log='League kickoff. Find space and make your mark.'}document.querySelectorAll('.subtabs button').forEach(b=>b.classList.remove('active'));el.classList.add('active');document.getElementById('compLabel').textContent=c.toUpperCase()+' · 1ST HALF';document.querySelector('.eyebrow').textContent=`${c.toUpperCase()} · ${s.club.toUpperCase()}`;updateMatchHud()}
function scenarioSucceeded(final){const stats=activeMatch.scenarioStats,goal=activeScenario.challenge.type;return goal==='corner'?stats.cornerGoals>=1:goal==='recover'?stats.recoveries>=1:goal==='pass'?stats.passes>=1:goal==='advance'?Boolean(activeMatch.advancedWithBall):goal==='shoot'?stats.onTarget>=1:goal==='win'?final==='Win':goal==='twoShots'?stats.shots>=2:goal==='brace'?stats.goals>=2:goal==='survive'?final!=null&&final!=='Loss':false}function scenarioProgress(final=null){const type=activeScenario.challenge.type,stats=activeMatch.scenarioStats;let detail=type==='corner'?`Far-corner goals ${Math.min(stats.cornerGoals,1)}/1`:type==='recover'?`Recoveries ${Math.min(stats.recoveries,1)}/1`:type==='pass'?`Passes ${Math.min(stats.passes,1)}/1`:type==='advance'?`Attacking area ${activeMatch.advancedWithBall?'reached with possession':'not reached with possession'}`:type==='shoot'?`On-target shots ${Math.min(stats.onTarget,1)}/1`:type==='twoShots'?`Shots ${Math.min(stats.shots,2)}/2`:type==='brace'?`Goals ${Math.min(stats.goals,2)}/2`:type==='win'?`${final?`Result ${final}`:'Need a win'}`:`${final?`Result ${final}`:'Avoid defeat'}`;return `${detail} · ${scenarioSucceeded(final)?'✓ COMPLETE':final?'MISSED':'IN PROGRESS'}`}
function endMatch(){if(!activeMatch||activeMatch.done)return;activeMatch.done=true;clearInterval(matchLoop);let final=activeMatch.home>activeMatch.away?'Win':activeMatch.home===activeMatch.away?'Draw':'Loss';if(final==='Win'){s.wins++;s.streak++}else s.streak=0;s.played++;s.energy=Math.max(12,s.energy-17);s.fitness=Math.max(20,s.fitness-6);s.money+=s.salary;let bonus=final==='Win'?900:final==='Draw'?350:120;s.money+=bonus;s.contract=Math.max(0,s.contract-1);s.week++;s.age=s.week%52===0?s.age+1:s.age;s.lastResults=[final[0],...(s.lastResults||[])].slice(0,5);s.lastResult=`${final} · ${activeMatch.home}–${activeMatch.away} · ${money(s.salary)} wages paid`;if(s.played%10===0)s.season++;save();let status=document.getElementById('matchStatus');if(status)status.textContent=`FULL TIME — ${final.toUpperCase()} · CHALLENGE ${scenarioSucceeded(final)?'COMPLETE':'MISSED'} · +${money(s.salary+bonus)}`;document.getElementById('continueBtn')?.classList.remove('hidden');document.querySelectorAll('.controls button').forEach(b=>b.disabled=true);let c=document.getElementById('compLabel');if(c)c.textContent=`${activeMatch.competition.toUpperCase()} · FULL TIME`;updateMatchHud()}
